<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import AccountingStatement from './AccountingStatement.vue';
import AccountingCombinedChart from './AccountingCombinedChart.vue';
const groupLabel=window.portal.workspaceGroupName||'';
const props=defineProps<{section:string}>();
const emit=defineEmits(['navigate']);
const today=new Date().toLocaleDateString('en-CA');
const reportAccount=ref<any>(null);
const from=ref(today.slice(0,7)+'-01'),to=ref(today),search=ref(''),status=ref(''),basis=ref('accrual'),trial=ref('6'),page=ref(1),result=ref<any>(null),loading=ref(false),error=ref('');let generation=0;
const titles:Record<string,string>={overview:'Combined financial overview',customers:'Customers',suppliers:'Suppliers',sales:'Sales invoices',purchases:'Purchase invoices',journals:'Journal entries','single-vouchers':'Single vouchers','cash-receipts':'Cash receipt vouchers','cash-payments':'Cash payment vouchers',chart:'Combined chart of accounts',ledger:'Combined General Ledger',trial:'Combined Trial Balance',profit:'Combined Profit and Loss',balance:'Combined Balance Sheet',receivables:'Combined accounts receivable',payables:'Combined accounts payable',books:'Company books',audit:'Audit history',approvals:'Approvals'};
const money=(v:any)=>Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
const combined=computed(()=>result.value?.mode==='combined');
const summaryFields=computed(()=>({overview:['cash_bank','receivables_outstanding','payables_outstanding','profit_income','profit_expense'],chart:['asset','liability','equity','income','expense','cash_bank'],trial:trial.value==='2'?['closing_debit','closing_credit']:['opening_debit','opening_credit','debit','credit','closing_debit','closing_credit'],profit:['income','expense','profit'],balance:['assets','liabilities','equity','accumulated_earnings','balance_difference'],ledger:['debit','credit'],receivables:['outstanding','current','days_1_30','days_31_60','days_61_90','over_90'],payables:['outstanding','current','days_1_30','days_31_60','days_61_90','over_90']} as Record<string,string[]>)[props.section]||[]);
const columnKeys=computed(()=>({overview:['company_name','cash_bank','receivables','payables','income','expenses'],books:['company_name','start_date','locked_through'],chart:['code','name','root_type','debit','credit','balance'],trial:trial.value==='2'?['code','name','closing_debit','closing_credit']:['code','name','opening_debit','opening_credit','debit','credit','closing_debit','closing_credit'],profit:['code','name','root_type','amount'],balance:['code','name','root_type','amount'],ledger:['company_name','posting_date','number','code','name','debit','credit','balance'],receivables:['company_name','number','party_name','due_date','total','paid','outstanding','overdue_days'],payables:['company_name','number','party_name','due_date','total','paid','outstanding','overdue_days']} as Record<string,string[]>)[props.section]||[]);
const labels:Record<string,string>={company_name:'Company',code:'Code',name:'Account',root_type:'Type',debit:'Debit',credit:'Credit',balance:'Balance',opening_debit:'Opening Dr',opening_credit:'Opening Cr',closing_debit:'Closing Dr',closing_credit:'Closing Cr',posting_date:'Date',number:'Document',party_name:'Contact',due_date:'Due date',total:'Total',outstanding:'Outstanding',paid:'Paid',overdue_days:'Days overdue',start_date:'Books start',locked_through:'Locked through',cash_bank:'Cash & Bank',receivables:'Receivables',payables:'Payables',income:'Income',expenses:'Expenses',expense:'Expenses',profit:'Net profit / loss',receivables_outstanding:'Customers owe you',payables_outstanding:'You owe suppliers',profit_income:'Income in period',profit_expense:'Expenses in period',assets:'Assets',asset:'Assets',liabilities:'Liabilities',liability:'Liabilities',equity:'Equity',accumulated_earnings:'Accumulated earnings',balance_difference:'Balance difference',current:'Current',days_1_30:'1-30 days',days_31_60:'31-60 days',days_61_90:'61-90 days',over_90:'Over 90 days',amount:'Amount'};
const monetary=new Set(['debit','credit','balance','opening_debit','opening_credit','closing_debit','closing_credit','amount','total','paid','outstanding','cash_bank','receivables','payables','income','expenses']);
function value(row:any,key:string){if(row[key]==null)return '-';return monetary.has(key)?money(row[key])+(key==='balance'&&row.balance_side?' '+row.balance_side:''):row[key];}
function showReportAccount(statement:any,id:string|number){reportAccount.value=statement.rows.find((row:any)=>row.account_id===id)||null;}
async function load(){const gen=++generation;loading.value=true;error.value='';try{const q=new URLSearchParams({workspace_group:new URLSearchParams(location.search).get('workspace_group')||'',section:props.section,from:from.value,to:to.value,page:String(page.value),search:search.value,status:status.value,basis:basis.value,trial_columns:trial.value});const r=await fetch('/accounting/api/all-companies?'+q,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);if(gen===generation)result.value=d;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>props.section,()=>{page.value=1;status.value='';result.value=null;reportAccount.value=null;void load();},{immediate:true});onBeforeUnmount(()=>generation++);
useAccountingLiveRefresh(()=>load(),()=>true);
useAccountingAlerts(error);
</script>
<template><section class="ac-all-companies"><div class="ac-section-heading"><div><p class="eyebrow">ALL COMPANIES / COMBINED VIEW</p><h2>{{titles[section]||section}}</h2><p class="muted">{{groupLabel?'Companies listed under '+groupLabel+'.':'One view across Accounting companies.'}} Exact source entries are available below.</p></div><span v-if="combined" class="ac-badge active">{{result.company_count}} companies</span></div>
<form class="ac-filters" @submit.prevent="page=1;load()"><label>{{combined?'Filter companies':'Search'}}<input v-model="search" :placeholder="combined?'Company name':'Company or record'" type="search"></label><template v-if="!['books','chart','customers','suppliers','audit','approvals'].includes(section)"><label>From<input v-model="from" type="date" required></label><label>To<input v-model="to" type="date" required :min="from"></label></template><label v-if="['sales','purchases','journals','single-vouchers','cash-receipts','cash-payments'].includes(section)">Status<select v-model="status"><option value="">All statuses</option><option value="draft">Non-posted</option><option value="posted">Posted</option><option value="reversed">Reversed</option></select></label><label v-if="section==='profit'">Accounting basis<select v-model="basis"><option value="accrual">Accrual basis</option><option value="cash">Cash basis</option></select></label><label v-if="section==='trial'">Trial Balance view<select v-model="trial"><option value="2">2 columns</option><option value="6">6 columns</option></select></label><button class="button primary" :disabled="loading">{{loading?'Loading...':'Update view'}}</button></form>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="loading" role="status">Loading combined accounts...</p>
<template v-if="result&&!loading"><div v-if="!combined&&result.totals?.length" class="ac-table-wrap ac-combined-totals"><table class="ac-finance-table"><caption>Combined document values - all matching records</caption><thead><tr><th>Currency</th><th>Documents</th><th>Posted document value</th><th>Non-posted document value</th><th>Reversed document value</th></tr></thead><tbody><tr v-for="group in result.totals" :key="group.currency"><td>{{group.currency}}</td><td>{{group.documents}}</td><td>{{money(group.posted_amount)}}</td><td>{{money(group.draft_amount)}}</td><td>{{money(group.reversed_amount)}}</td></tr></tbody></table><p class="ac-combined-note">Document values are shown separately by status; drafts do not affect financial reports.</p></div><template v-if="combined"><p class="muted ac-combined-note">Totals cover every matching company, across all pages. Currencies are kept separate; no currency conversion or intercompany eliminations are applied.</p><p v-if="result.unconfigured_companies" class="ac-help">{{result.unconfigured_companies}} companies have no books configured and contribute no financial amounts.</p>
<section v-if="section==='overview'" v-for="group in result.totals" :key="group.currency" class="ac-combined-overview"><div class="ac-section-heading"><div><p class="eyebrow">FINANCIAL OVERVIEW</p><h3>Your companies at a glance</h3></div><span class="ac-badge active">{{group.currency}}</span></div><div class="ac-stats ac-overview-stats"><button v-for="card in [{key:'receivables_outstanding',section:'receivables'},{key:'payables_outstanding',section:'payables'},{key:'profit_income',section:'profit'},{key:'profit_expense',section:'profit'},{key:'cash_bank',section:'chart'}]" :key="card.key" @click="emit('navigate',card.section)"><small>{{labels[card.key]}}</small><strong>{{money(group.summary[card.key])}}</strong><span>View details &#8594;</span></button></div></section><div v-if="section==='overview'" class="ac-overview-panels ac-overview-actions"><article class="ac-books-panel"><p class="eyebrow">QUICK ACTIONS</p><h3>Accounting shortcuts</h3><div class="ac-quick-actions"><button class="button" @click="emit('navigate','sales')">Sales invoices &#8594;</button><button class="button" @click="emit('navigate','purchases')">Purchase invoices &#8594;</button><button class="button" @click="emit('navigate','journals')">Journal entries &#8594;</button><button class="button" @click="emit('navigate','trial')">Trial Balance &#8594;</button></div></article></div><div v-if="summaryFields.length&& section!=='overview'" class="ac-table-wrap ac-combined-totals"><table class="ac-finance-table"><caption>Combined totals</caption><thead><tr><th>Currency</th><th>Companies</th><th v-for="key in summaryFields" :key="key">{{labels[key]}}</th></tr></thead><tbody><tr v-for="group in result.totals" :key="group.currency"><td><strong>{{group.currency}}</strong></td><td>{{group.companies}}</td><td v-for="key in summaryFields" :key="key" class="numeric"><strong>{{money(group.summary[key])}}</strong></td></tr></tbody></table></div>
<details v-if="result.cash_basis_review?.length" class="ac-help"><summary>Cash-basis review needed: {{result.cash_basis_review.length}} entries excluded</summary><p>These totals are incomplete until the unallocated entries are reviewed.</p><p v-for="entry in result.cash_basis_review" :key="entry.company_id+'-'+entry.id"><a :href="entry.url">{{entry.company_name}} / {{entry.number}}</a> - {{entry.reason}}</p></details>
<p v-if="['chart','trial','profit','balance'].includes(section)" class="muted">Matching accounts combine only when their code, name, type and full parent hierarchy match. Expand a row to see each company's contribution.</p>
<AccountingCombinedChart v-if="section==='chart'" :accounts="result.records.data"/><div v-else-if="['profit','balance'].includes(section)" class="ac-chart-layout has-selection"><div><AccountingStatement v-for="statement in result.statements||[]" :key="statement.currency" :report="section" :result="statement" :company-name="'All companies / '+statement.currency" @account="id=>showReportAccount(statement,id)"/></div><aside class="ac-detail" aria-label="Report account details"><template v-if="reportAccount"><div class="ac-detail-heading"><span class="ac-badge active">{{reportAccount.currency}}</span><button class="ac-detail-close" aria-label="Close report account details" @click="reportAccount=null">&#215;</button></div><code>{{reportAccount.code}}</code><h3>{{reportAccount.name}}</h3><p>Combined amount: <strong>{{money(reportAccount.amount)}}</strong></p><h4>Company contributions</h4><div v-for="source in reportAccount.contributors" :key="source.company_id" class="ac-contributions"><a :href="source.url">{{source.company_name}}</a><p>{{money(source.amount)}} {{reportAccount.currency}}</p></div></template><template v-else><p class="eyebrow">REPORT DETAILS</p><h3>View account details</h3><p class="muted">Select an account in the statement to view its company contributions and source ledger links.</p></template></aside></div><div v-else class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Currency</th><th v-for="key in columnKeys" :key="key">{{key==='balance'&& section==='ledger'?'Company running balance':labels[key]}}</th><th>Details</th></tr></thead><tbody><template v-for="(row,index) in result.records.data" :key="row.key||row.company_id+'-'+(row.id||index)"><tr><td>{{row.currency||'Not configured'}}</td><td v-for="key in columnKeys" :key="key" :class="{numeric:monetary.has(key)}">{{value(row,key)}}</td><td><details v-if="row.contributors?.length" class="ac-contributions"><summary>{{row.contributors.length}} companies</summary><div v-for="source in row.contributors" :key="source.company_id"><a :href="source.url">{{source.company_name}}</a><small v-if="section==='chart'||section==='trial'">Dr {{money(source.debit)}} / Cr {{money(source.credit)}}</small><small v-else>{{money(source.amount)}} {{row.currency}}</small></div></details><a v-else class="button" :href="row.url">Open</a></td></tr></template></tbody></table></div></template>
<div v-else class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Company</th><th>Record</th><th>Person / description</th><th>Status / activity</th><th>Date</th><th>Currency</th><th>Amount</th><th></th></tr></thead><tbody><tr v-for="row in result.records.data" :key="row.id"><td>{{row.company_name}}</td><td><a :href="row.url">{{row.number||row.name||row.subject||('Approval #'+row.id)}}</a></td><td>{{row.party_name||row.voucher_person||row.email||row.actor_name||row.remarks||row.document_type||'-'}}</td><td>{{row.status==='draft'?'Non-posted':row.status||row.stage||row.action||(row.active?'Active':'Inactive')}}</td><td>{{row.posting_date||row.created_at||'-'}}</td><td>{{row.currency||'-'}}</td><td>{{row.amount?money(row.amount):'-'}}</td><td><a class="button" :href="row.url">Open</a></td></tr></tbody></table></div>
<p v-if="!result.records.data.length" class="ac-empty-small">No matching records.</p><div class="ac-pagination"><span>Page {{result.records.current_page}} of {{result.records.last_page}} &#183; {{result.records.total}} records</span><button class="button" :disabled="page<=1" @click="page--;load()">Previous</button><button class="button" :disabled="page>=result.records.last_page" @click="page++;load()">Next</button></div></template></section></template>
<style scoped>.ac-all-companies .ac-filters{flex-wrap:wrap}.ac-all-companies .ac-filters label{min-width:140px}.ac-all-companies .ac-table-wrap{max-width:100%;overflow:auto;margin:18px 0}.ac-combined-totals{border:1px solid var(--line);border-radius:12px;background:var(--rail)}.ac-combined-totals caption{text-align:left;padding:16px;font-weight:600}.ac-combined-totals tbody td{padding-top:18px;padding-bottom:18px}.ac-contributions{min-width:100px}.ac-contributions summary{cursor:pointer;color:#7665ed;font-size:12px}.ac-contributions>div{display:flex;flex-direction:column;gap:5px;padding:10px 0;border-bottom:1px solid var(--line)}.ac-contributions small{color:var(--muted);white-space:nowrap}.ac-combined-note{font-size:12px;line-height:1.6}</style>
